(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.AngleLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function piTex(n,d=180){const q=num.rational(n,d);if(q.n===0)return '0';const sign=q.n<0?'-':'',top=Math.abs(q.n)===1?'\\pi':Math.abs(q.n)+'\\pi';return sign+(q.d===1?top:`\\frac{${top}}{${q.d}}`);}
function decimal(n,d=3){return n.toFixed(d).replace('.','{,}');}
function path(points){return points.map((p,i)=>`${i===0?'M':'L'}${p.x} ${p.y}`).join(' ');}
function draw(){const one=$('[name="angle-mode"]:checked').value==='one',degrees=Number($('#angle-degrees').value),theta=one?1:core.radians(degrees),r=Number($('#angle-radius').value),R=r*40,p=core.point(R,theta),length=core.arcLength(r,theta);$('#degree-control').hidden=one;$('#one-radian-note').hidden=!one;$('#angle-output').value=degrees+'°';$('#radius-output').value=r;$('#angle-circle').setAttribute('r',R);$('#initial-ray').setAttribute('x2',180+R);$('#terminal-ray').setAttribute('x2',p.x);$('#terminal-ray').setAttribute('y2',p.y);$('#terminal-dot').setAttribute('cx',p.x);$('#terminal-dot').setAttribute('cy',p.y);$('#angle-arc').setAttribute('d',path(core.arc(R,theta)));$('#direction-arc').setAttribute('d',path(core.arc(27,Math.sign(theta)*Math.min(Math.abs(theta),Math.PI/2))));if(one){math($('#angle-equation'),`\\theta=1\\text{ rad}\\approx${decimal(core.degrees(1))}^\\circ`);math($('#arc-equation'),`s=${r}\\cdot1=${r},\\qquad\\frac{s}{r}=1`);}else{math($('#angle-equation'),`\\theta=${degrees}^\\circ=${piTex(degrees)}\\text{ rad}`);math($('#arc-equation'),`s=r|\\theta|=${piTex(r*Math.abs(degrees))}\\approx${decimal(length)}`);}const direction=theta===0?'Tidak ada putaran; sisi awal dan akhir berimpit.':theta>0?'Putaran positif: berlawanan arah jarum jam.':'Putaran negatif: searah jarum jam.';$('#angle-feedback').innerHTML=direction+' '+(one?'Panjang busur sama dengan jari-jari. Mengubah ukuran lingkaran tidak mengubah sudut satu radian.':Math.abs(degrees)===360?'Satu putaran penuh membuat sisi akhir berimpit dengan sisi awal. Panjang busur sama dengan keliling lingkaran.':'Panjang busur selalu tidak negatif; tanda sudut menyatakan arah putaran.')+` Panjang busur memakai satuan panjang yang sama dengan jari-jari.`;$('#angle-plot').setAttribute('aria-label',`Lingkaran berjari-jari ${r}. Sudut ${one?'tepat satu radian':degrees+' derajat'}. ${direction} Panjang busur sekitar ${length.toFixed(3)} satuan panjang.`);}
['angle-degrees','angle-radius'].forEach(id=>$('#'+id).addEventListener('input',draw));document.querySelectorAll('[name="angle-mode"]').forEach(e=>e.addEventListener('change',draw));document.querySelectorAll('[data-angle]').forEach(button=>button.addEventListener('click',()=>{$('#angle-degrees').value=button.dataset.angle;draw();}));draw();
const rows=[[0,'0','Nol'],[30,'\\pi/6','Seperdua belas'],[45,'\\pi/4','Seperdelapan'],[60,'\\pi/3','Seperenam'],[90,'\\pi/2','Seperempat'],[180,'\\pi','Setengah'],[270,'3\\pi/2','Tiga perempat'],[360,'2\\pi','Satu']];$('#angle-table').innerHTML=rows.map(([d,r,part])=>`<tr><th scope="row"><span data-tex="${d}^\\circ"></span></th><td><span data-tex="${r}"></span></td><td>${part}</td></tr>`).join('');
const questions=[{tex:'150^\\circ=q\\pi\\text{ rad}',prompt:'Berapa koefisien pi pada bentuk radian? Tulis bilangannya saja, tanpa pi.',n:5,d:6,hint:'Bagi jumlah derajat dengan seratus delapan puluh, lalu sederhanakan pecahannya.',why:'Seratus lima puluh dibagi seratus delapan puluh sama dengan lima perenam. Jadi sudutnya lima pi per enam radian.'},{tex:'\\theta=\\frac{3\\pi}{4}\\text{ rad}',prompt:'Berapa besar sudut ini dalam derajat?',n:135,d:1,hint:'Kalikan tiga perempat dengan seratus delapan puluh.',why:'Pi saling menghapus pada faktor konversi; tiga perempat dari seratus delapan puluh adalah seratus tiga puluh lima derajat.'},{tex:'r=3,\\quad\\theta=\\frac\\pi3\\text{ rad},\\quad s=q\\pi',prompt:'Berapa koefisien pi pada panjang busur?',n:1,d:1,hint:'Kalikan jari-jari dengan sudut dalam radian.',why:'Tiga dikali pi per tiga sama dengan pi satuan panjang, sehingga koefisiennya satu.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan atau pecahan, misalnya 5/6.':'Belum tepat. Periksa satuan sudut dan apakah jawaban diminta sebagai koefisien pi.');}));
const choices=[{tex:'-90^\\circ',prompt:'Putaran mana yang sesuai dengan sudut ini dalam posisi standar?',options:['Seperempat putaran berlawanan arah jarum jam.','Seperempat putaran searah jarum jam.','Setengah putaran searah jarum jam.'],answer:1,why:'Tanda negatif berarti searah jarum jam. Sembilan puluh derajat adalah seperempat putaran.'},{tex:'\\theta=1\\text{ rad}',prompt:'Jika jari-jari diperbesar dari dua menjadi empat satuan panjang, apa yang terjadi?',options:['Panjang busur menjadi dua kali, tetapi besar sudut tetap satu radian.','Besar sudut menjadi dua radian karena lingkarannya membesar.','Panjang busur tetap dua satuan panjang.'],answer:0,why:'Pada satu radian, panjang busur sama dengan jari-jari. Keduanya membesar dengan faktor sama, sehingga perbandingannya tetap satu.'},{tex:'30^\\circ\\quad\\text{dan}\\quad390^\\circ',prompt:'Pernyataan mana yang benar?',options:['Kedua sudut sama besar karena arah akhirnya sama.','Arah akhir keduanya berbeda karena angkanya berbeda.','Arah akhir sama, tetapi sudut kedua memiliki satu putaran tambahan.'],answer:2,why:'Selisihnya satu putaran penuh. Keduanya sekoterminal, tetapi jumlah putarannya berbeda.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-angle-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-angle-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();